package com.arjunren.banking.controller;
import com.arjunren.banking.dto.Dtos.*; import com.arjunren.banking.entity.AppUser; import com.arjunren.banking.service.BankingService; import jakarta.validation.Valid; import java.util.Map; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class AccountController{private final BankingService banking;public AccountController(BankingService banking){this.banking=banking;}@GetMapping("/accounts")Map<String,Object> accounts(@AuthenticationPrincipal AppUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",banking.accounts(u,page,Math.min(Math.max(size,1),100)));}@GetMapping("/accounts/{id}")Map<String,Object> account(@PathVariable Long id,@AuthenticationPrincipal AppUser u){return Map.of("data",banking.account(id,u));}@PostMapping("/accounts/{id}/deposit")Map<String,Object> deposit(@PathVariable Long id,@Valid @RequestBody MoneyRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",banking.deposit(id,r.amount(),r.description(),u));}@PostMapping("/accounts/{id}/withdraw")Map<String,Object> withdraw(@PathVariable Long id,@Valid @RequestBody MoneyRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",banking.withdraw(id,r.amount(),r.description(),u));}@PostMapping("/transfers")@ResponseStatus(HttpStatus.NO_CONTENT)void transfer(@Valid @RequestBody TransferRequest r,@AuthenticationPrincipal AppUser u){banking.transfer(r,u);}@GetMapping("/accounts/{id}/transactions")Map<String,Object> history(@PathVariable Long id,@AuthenticationPrincipal AppUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",banking.history(id,u,page,Math.min(Math.max(size,1),100)));}@GetMapping("/dashboard")Map<String,Object> dashboard(@AuthenticationPrincipal AppUser u){return Map.of("data",banking.accounts(u,0,100));}}

